INSERT INTO "vocabflow_app"."vocabulary_topics" ("vocabulary_id", "topic_id")
SELECT v."id", t."id"
FROM "vocabflow_app"."vocabularies" v
JOIN "vocabflow_app"."topics" t ON t."source_topic" = v."topic"
WHERE v."source_dataset" = '2000_COMMON_ENGLISH_VOCABULARY_V1'
  AND v."source_record_id" IS NOT NULL
ON CONFLICT ("vocabulary_id", "topic_id") DO NOTHING;
